// Package generate writes the files hecatron generates for a project
// (docs/design.md §11): its Dockerfile, from each language's dockerfile
// snippet, and its CI workflows, from each language's workflow.yml, each
// under a DO NOT EDIT banner. It is a port of libexec/codegen/dockerfile.py,
// banner.py and manage.py's workflow code and must write what they write,
// byte for byte; where they would depend on a Python quirk it declines
// (project.IsUnsupported) and the command is left to them.
package generate

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"unicode/utf8"

	"github.com/dnf/hecatron/internal/project"
)

// bannerWidth is the banner's inner width, in characters.
const bannerWidth = 62

// Banner is banner.py's make_banner: a 9-line box-frame DO NOT EDIT banner
// around five rows, each line wrapped in prefix and suffix.
func Banner(rows []string, prefix, suffix string) string {
	line := func(content string) string { return prefix + content + suffix + "\n" }
	bar := strings.Repeat("═", bannerWidth)
	var out strings.Builder
	out.WriteString(line("╔" + bar + "╗"))
	out.WriteString(line("║" + center("DO NOT EDIT THIS FILE", bannerWidth) + "║"))
	out.WriteString(line("╠" + bar + "╣"))
	for _, row := range rows {
		out.WriteString(line("║ " + ljust(row, bannerWidth-2) + " ║"))
	}
	out.WriteString(line("╚" + bar + "╝"))
	return out.String()
}

// center is Python's str.center: the odd space on the right for an even
// width.
func center(text string, width int) string {
	margin := width - utf8.RuneCountInString(text)
	if margin <= 0 {
		return text
	}
	left := margin/2 + (margin & width & 1)
	return strings.Repeat(" ", left) + text + strings.Repeat(" ", margin-left)
}

func ljust(text string, width int) string {
	if n := utf8.RuneCountInString(text); n < width {
		return text + strings.Repeat(" ", width-n)
	}
	return text
}

// Write is manage.py's write_if_changed: content written to path unless it
// is already there (read as Python reads text, so a file differing only in
// line ends is current), or, with check, only whether it is. It reports
// what it did as manage.py does ("wrote X", "out of date: X") and returns
// whether the file is current.
func Write(path, content, label string, check bool, out *strings.Builder) (bool, error) {
	if info, err := os.Stat(path); err == nil && info.Mode().IsRegular() {
		current, err := project.ReadPyText(path)
		if err != nil {
			return false, err
		}
		if current == content {
			return true, nil
		}
	}
	if check {
		fmt.Fprintf(out, "out of date: %s\n", label)
		return false, nil
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o777); err != nil {
		return false, err
	}
	if err := os.WriteFile(path, []byte(content), 0o666); err != nil {
		return false, err
	}
	fmt.Fprintf(out, "wrote %s\n", label)
	return true, nil
}

// basePackages are always installed: build tools, what snippets download
// with, and what hecatron itself runs on.
var basePackages = []string{"build-essential", "ca-certificates", "curl", "git", "gnupg", "perl", "python3", "unzip"}

const (
	eachVersion    = "# each-version"
	endEachVersion = "# end-each-version"
)

// snippet is a language's dockerfile snippet, parsed.
type snippet struct {
	apt   []string
	body  []string
	after string
}

func parseSnippet(p *project.Project, lang string) (snippet, error) {
	path := p.Resolve(lang, "dockerfile")
	if path == "" {
		return snippet{}, nil
	}
	text, err := project.ReadPyText(path)
	if err != nil {
		return snippet{}, err
	}
	var s snippet
	var lines []string
	for _, line := range splitFileLines(text) {
		switch {
		case strings.HasPrefix(line, "# apt:"):
			s.apt = append(s.apt, project.PyFields(strings.TrimPrefix(line, "# apt:"))...)
		case strings.HasPrefix(line, "# after:"):
			s.after = project.PyStrip(strings.TrimPrefix(line, "# after:"))
		default:
			lines = append(lines, line)
		}
	}
	s.body, err = expandVersions(p, lang, lines, path)
	return s, err
}

// splitFileLines is Python's `for line in f` with each line's "\n" removed.
func splitFileLines(text string) []string {
	if text == "" {
		return nil
	}
	return strings.Split(strings.TrimSuffix(text, "\n"), "\n")
}

// blockVersions are the specs an each-version block repeats for: the
// definition's default, then every other spec the components resolve to.
func blockVersions(p *project.Project, lang string) ([]string, error) {
	var specs []string
	defaultVersion, err := p.DefaultVersion(lang)
	if err != nil {
		return nil, err
	}
	if defaultVersion != "" {
		specs = append(specs, defaultVersion)
	}
	resolved, err := p.Versions(lang)
	if err != nil {
		return nil, err
	}
	for _, s := range resolved {
		if s.Spec != "" && !contains(specs, s.Spec) {
			specs = append(specs, s.Spec)
		}
	}
	return specs, nil
}

func contains(list []string, item string) bool {
	for _, entry := range list {
		if entry == item {
			return true
		}
	}
	return false
}

// fillVersion fills {version}, {exact}, {major} and {minor} in a block
// line; other braces (shell's ${VAR}) pass through.
func fillVersion(line, spec string) string {
	version := strings.TrimLeft(spec, "=")
	parts := strings.Split(version, ".")
	exact, minor := "", ""
	if strings.HasPrefix(spec, "=") {
		exact = "1"
	}
	if len(parts) > 1 {
		minor = parts[1]
	}
	for _, field := range [][2]string{{"version", version}, {"exact", exact}, {"major", parts[0]}, {"minor", minor}} {
		line = strings.ReplaceAll(line, "{"+field[0]+"}", field[1])
	}
	return line
}

// expandVersions writes each `# each-version [LANG]` ... `# end-each-version`
// block once per spec of LANG (the snippet's own language if none).
func expandVersions(p *project.Project, lang string, lines []string, source string) ([]string, error) {
	var out, block []string
	inBlock, blockLang := false, lang
	for _, line := range lines {
		switch {
		case line == eachVersion || strings.HasPrefix(line, eachVersion+" "):
			if inBlock {
				return nil, &project.Error{Message: source + ": each-version blocks don't nest"}
			}
			inBlock, block = true, nil
			if blockLang = project.PyStrip(line[len(eachVersion):]); blockLang == "" {
				blockLang = lang
			}
		case line == endEachVersion:
			if !inBlock {
				return nil, &project.Error{Message: fmt.Sprintf("%s: %s without %s", source, endEachVersion, eachVersion)}
			}
			specs, err := blockVersions(p, blockLang)
			if err != nil {
				return nil, err
			}
			for _, spec := range specs {
				for _, blockLine := range block {
					out = append(out, fillVersion(blockLine, spec))
				}
			}
			inBlock = false
		case inBlock:
			block = append(block, line)
		default:
			out = append(out, line)
		}
	}
	if inBlock {
		return nil, &project.Error{Message: fmt.Sprintf("%s: %s without %s", source, eachVersion, endEachVersion)}
	}
	return out, nil
}

func hasBody(lines []string) bool {
	for _, line := range lines {
		if strings.HasPrefix(line, "RUN ") || strings.HasPrefix(line, "ENV ") {
			return true
		}
	}
	return false
}

// topologicalSort orders languages after the ones their "# after:" names
// (those that are active), else alphabetically (Kahn's algorithm).
func topologicalSort(languages []string, after map[string]string, active map[string]bool) []string {
	graph := map[string][]string{}
	inDegree := map[string]int{}
	for _, lang := range languages {
		inDegree[lang] = 0
	}
	for _, lang := range languages {
		dependency := after[lang]
		if _, known := inDegree[dependency]; dependency != "" && active[dependency] && known {
			graph[dependency] = append(graph[dependency], lang)
			inDegree[lang]++
		}
	}
	var queue, result []string
	for _, lang := range languages {
		if inDegree[lang] == 0 {
			queue = append(queue, lang)
		}
	}
	sort.Strings(queue)
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		result = append(result, current)
		neighbours := append([]string(nil), graph[current]...)
		sort.Strings(neighbours)
		for _, neighbour := range neighbours {
			if inDegree[neighbour]--; inDegree[neighbour] == 0 {
				i := 0
				for i < len(queue) && queue[i] < neighbour {
					i++
				}
				queue = append(queue[:i], append([]string{neighbour}, queue[i:]...)...)
			}
		}
	}
	return result
}

// Dockerfile is dockerfile.py's generate: the project's Dockerfile.
func Dockerfile(p *project.Project) (string, error) {
	apt := append([]string(nil), basePackages...)
	bodies := map[string][]string{}
	after := map[string]string{}
	active := map[string]bool{}
	for _, lang := range p.Languages {
		active[lang] = true
		s, err := parseSnippet(p, lang)
		if err != nil {
			return "", err
		}
		apt = append(apt, s.apt...)
		bodies[lang] = s.body
		after[lang] = s.after
	}
	unique := map[string]bool{}
	var packages []string
	for _, pkg := range apt {
		if !unique[pkg] {
			unique[pkg] = true
			packages = append(packages, pkg)
		}
	}
	sort.Strings(packages)
	var withBody []string
	for _, lang := range p.Languages {
		if hasBody(bodies[lang]) {
			withBody = append(withBody, lang)
		}
	}
	banner := Banner([]string{
		"Generated by: hecatron dockerfile",
		"from each language's dockerfile snippet",
		"",
		"To regenerate: hecatron dockerfile",
		"Regenerated automatically by: hecatron add / remove",
	}, "# ", "")
	lines := []string{strings.TrimRight(banner, "\n"), "", "FROM ubuntu:24.04", "",
		"ENV DEBIAN_FRONTEND=noninteractive", "ENV LANG=C.UTF-8", "",
		"# System packages + language runtimes available from distro",
		"RUN apt-get update && apt-get install -y --no-install-recommends \\"}
	for _, pkg := range packages {
		lines = append(lines, "    "+pkg+" \\")
	}
	lines = append(lines, "    && rm -rf /var/lib/apt/lists/*", "")
	for _, lang := range topologicalSort(withBody, after, active) {
		body := bodies[lang]
		for len(body) > 0 && body[0] == "" {
			body = body[1:]
		}
		for len(body) > 0 && body[len(body)-1] == "" {
			body = body[:len(body)-1]
		}
		if len(body) > 0 {
			lines = append(append(lines, body...), "")
		}
	}
	if info, err := os.Stat(filepath.Join(p.Root, "justfile")); err == nil && info.Mode().IsRegular() {
		lines = append(lines, "# just (task runner)",
			"RUN curl --proto '=https' --tlsv1.2 -sSf https://just.systems/install.sh | bash -s -- --to /usr/local/bin", "")
	}
	lines = append(lines, "WORKDIR /workspace", "", `CMD ["bash"]`, "")
	return strings.Join(lines, "\n"), nil
}

// WorkflowPath is where a language's workflow goes (generated.workflows
// with {lang} filled in), "" when the project generates none.
func WorkflowPath(p *project.Project, lang string) (string, error) {
	template, err := p.Generated("workflows")
	if err != nil || template == "" {
		return "", err
	}
	return project.PyJoin(p.Root, strings.ReplaceAll(template, "{lang}", lang)), nil
}

// Workflow is a language's workflow: its workflow.yml under a banner; ok is
// false when the language has none.
func Workflow(p *project.Project, lang string) (content string, ok bool, err error) {
	source := p.Resolve(lang, "workflow.yml")
	if source == "" {
		return "", false, nil
	}
	body, err := project.ReadPyText(source)
	if err != nil {
		return "", false, err
	}
	banner := Banner([]string{
		"Source: " + project.PyRelpath(source, p.Root),
		"Generated by: hecatron workflows",
		"",
		"To update: edit the source, then run hecatron workflows",
		"(hecatron add and remove regenerate it too)",
	}, "# ", "")
	return banner + WithTimeouts(body, p.CITimeoutMinutes(lang)), true, nil
}

func yamlContent(line string) bool {
	text := strings.Trim(line, " \t\r")
	return text != "" && !strings.HasPrefix(text, "#")
}

func yamlIndent(line string) int { return len(line) - len(strings.TrimLeft(line, " ")) }

// WithTimeouts is manage.py's with_timeouts: the workflow with
// `timeout-minutes: <minutes>` after the runs-on of each job in its
// top-level jobs: that sets no timeout-minutes. A job without runs-on (one
// calling a reusable workflow) can't have one. The text is otherwise left as
// written.
func WithTimeouts(body, minutes string) string {
	lines := strings.Split(body, "\n")
	start := -1
	for i, line := range lines {
		if strings.TrimRight(line, " \t\r") == "jobs:" {
			start = i
			break
		}
	}
	if start < 0 {
		return body
	}
	type job struct {
		indent, runsOn int
		timeout        bool
	}
	var inserts [][2]int
	finish := func(j job) {
		if j.runsOn >= 0 && !j.timeout {
			inserts = append(inserts, [2]int{j.runsOn, j.indent})
		}
	}
	jobIndent := -1
	current := job{indent: -1, runsOn: -1}
	for i := start + 1; i < len(lines); i++ {
		line := lines[i]
		if !yamlContent(line) {
			continue
		}
		indent := yamlIndent(line)
		if indent == 0 {
			break
		}
		if jobIndent < 0 {
			jobIndent = indent
		}
		if indent <= jobIndent {
			finish(current)
			current = job{indent: -1, runsOn: -1}
			continue
		}
		if current.indent < 0 {
			current.indent = indent
		}
		if indent != current.indent {
			continue
		}
		key, _, _ := strings.Cut(strings.Trim(line, " \t\r"), ":")
		switch key {
		case "timeout-minutes":
			current.timeout = true
		case "runs-on":
			end := i
			for j := i + 1; j < len(lines); j++ {
				if !yamlContent(lines[j]) {
					continue
				}
				if yamlIndent(lines[j]) <= indent {
					break
				}
				end = j
			}
			current.runsOn = end
		}
	}
	finish(current)
	for k := len(inserts) - 1; k >= 0; k-- {
		at, indent := inserts[k][0]+1, inserts[k][1]
		line := strings.Repeat(" ", indent) + "timeout-minutes: " + minutes
		lines = append(lines[:at], append([]string{line}, lines[at:]...)...)
	}
	return strings.Join(lines, "\n")
}

// CoverageProblems are manage.py's workflow_coverage_problems: each
// language's workflow must test every component it implements.
func CoverageProblems(p *project.Project) ([]string, error) {
	if len(p.Components) == 1 && p.Components[0] == "." {
		return nil, nil
	}
	var problems []string
	for _, lang := range p.Languages {
		source := p.Resolve(lang, "workflow.yml")
		if source == "" {
			continue
		}
		text, err := project.ReadPyText(source)
		if err != nil {
			return nil, err
		}
		// A matrix over components (`${{ matrix.component }}` in the path)
		// covers them all.
		matrixPath := strings.ReplaceAll(strings.ReplaceAll(p.ImplTemplate(lang), "{component}", "${{ matrix.component }}"), "{lang}", lang)
		if strings.Contains(text, matrixPath) && containsAll(text, p.Components) {
			continue
		}
		dirs, err := p.ImplDirs(lang)
		if err != nil {
			return nil, err
		}
		for _, dir := range dirs {
			relative := project.PyRelpath(dir.Dir, p.Root)
			if !strings.Contains(text, relative) {
				problems = append(problems, fmt.Sprintf("%s: workflow doesn't test %s (%s)", lang, dir.Component, relative))
			}
		}
	}
	return problems, nil
}

func containsAll(text string, items []string) bool {
	for _, item := range items {
		if !strings.Contains(text, item) {
			return false
		}
	}
	return true
}
